// Long-polling de Telegram. El offset vive en la static data del workflow, asi
// que sobrevive reinicios y cortes de luz: cada mensaje se procesa UNA vez.
//
// POR QUE POLLING Y NO EL NODO "Telegram Trigger": ese nodo registra un webhook
// y Telegram necesita ENTRAR a n8n desde internet. S1 esta detras del router del
// local, sin IP publica. Con polling S1 SALE a internet (que ya puede) y no hay
// que abrir puertos ni depender de un tunel que se caiga.
const est = $getWorkflowStaticData('global');
const token = $env.TELEGRAM_BOT_TOKEN;
if (!token) throw new Error('Falta TELEGRAM_BOT_TOKEN en el entorno de n8n');

const offset = est.offset ?? 0;

// Cuantos mensajes se toman POR CORRIDA. Mandar un album de 20 fotos hacia que
// una sola ejecucion encadenara 20 OCR (~30-60s cada uno) y se estirara varios
// MINUTOS. Con el lote acotado, cada corrida termina rapido y el resto entra en
// los disparos siguientes.
const LOTE = 10;

// timeout EXPLICITO. Sin el, la consulta se puede colgar y morir recien a los
// 120s con un 504: como el trigger dispara cada minuto, para entonces ya hay
// dos ejecuciones encimadas, y dos getUpdates simultaneos con el MISMO token
// se pisan entre si (Telegram corta uno con 409 y deja al otro colgado). Eso
// se realimenta y el workflow no vuelve solo. Con 20s, una consulta nunca
// llega viva al disparo siguiente.
let resp;
try {
  resp = await this.helpers.httpRequest({
    url: `https://api.telegram.org/bot${token}/getUpdates`,
    qs: { offset, timeout: 0, limit: LOTE, allowed_updates: JSON.stringify(['message']) },
    json: true,
    timeout: 20000,
  });
} catch (e) {
  // Un poller no tiene que gritar por un problema pasajero: el minuto que
  // viene reintenta solo. Se registra y se devuelve vacio, en vez de dejar la
  // ejecucion en rojo cada minuto y tapar los errores que si importan.
  const codigo = e.httpCode ?? e.response?.status ?? '';
  const conflicto = String(codigo) === '409';
  console.log(
    'No se pudo consultar Telegram' + (codigo ? ' (HTTP ' + codigo + ')' : '') + ': ' +
    (e.message ?? e) +
    (conflicto || String(codigo) === '504'
      ? ' | 409/504 = HAY OTRO n8n POLEANDO EL MISMO BOT. Revisa que no haya' +
        ' una segunda instancia (otra PC, o el workflow abierto en el editor).' +
        ' Para probar en otra maquina usa un bot aparte de @BotFather.'
      : ''),
  );
  return [];
}
if (!resp.ok) throw new Error('getUpdates fallo: ' + JSON.stringify(resp));

// Whitelist. Acepta las DOS formas en que uno tiene el dato a mano: el ID
// numerico (from.id) o el @usuario. El @usuario es lo que se ve en Telegram, asi
// que es lo que uno carga sin pensarlo; aceptar solo numeros hacia que el
// workflow terminara "Succeeded" sin procesar nada ni decir por que.
// Preferir el ID numerico igual: el @usuario se puede soltar y otro tomarlo.
const permitidos = String($env.TELEGRAM_ALLOWED_IDS || '')
  .split(',').map((s) => s.trim()).filter(Boolean);
const idsOk = permitidos.filter((p) => /^\d+$/.test(p));
const usuariosOk = permitidos.filter((p) => !/^\d+$/.test(p))
  .map((p) => p.replace(/^@/, '').toLowerCase());

const out = [];
const rechazados = [];
let maxId = offset - 1;
for (const up of resp.result || []) {
  maxId = Math.max(maxId, up.update_id);
  const msg = up.message;
  if (!msg) continue;
  const chatId = msg.chat?.id;
  const fromId = String(msg.from?.id ?? '');
  const usuario = String(msg.from?.username ?? '').toLowerCase();
  // Sin lista configurada NO se acepta a nadie: un bot de Telegram es publico y
  // cualquiera que adivine el nombre puede escribirle. Falla cerrado a proposito.
  const permitido = idsOk.includes(fromId) || (usuario && usuariosOk.includes(usuario));
  if (!permitidos.length || !permitido) {
    // Se descarta en silencio para el de afuera (contestarle a un desconocido le
    // confirma que el bot existe), pero SI queda en el log de la ejecucion: sin
    // eso el workflow termina "Succeeded" sin una sola pista de por que.
    rechazados.push(fromId + (usuario ? ' (@' + usuario + ')' : ' (sin @usuario)'));
    continue;
  }

  let fileId = null;
  if (Array.isArray(msg.photo) && msg.photo.length) {
    fileId = msg.photo[msg.photo.length - 1].file_id;   // mayor resolucion
  } else if (msg.document) {
    const mt = msg.document.mime_type || '';
    if (mt.startsWith('image/') || mt === 'application/pdf') fileId = msg.document.file_id;
  }
  out.push({ json: { chatId, fromId, fileId, sinArchivo: !fileId } });
}
// El offset avanza SIEMPRE, aun si un mensaje falla despues: si no, una factura
// ilegible se reprocesaria en loop cada minuto para siempre.
est.offset = maxId + 1;

// Y ADEMAS se le confirma a Telegram en el acto. Esto no es redundante: n8n
// guarda la static data al TERMINAR la ejecucion, no cuando se la escribe. Con
// un album de fotos, la corrida se estira minutos haciendo OCR, el trigger
// vuelve a disparar al minuto, la ejecucion nueva lee el offset VIEJO de la
// base y se trae LOS MISMOS mensajes. Cada foto terminaba procesandose una vez
// por cada ejecucion encimada -> el diluvio de "Esa factura ya estaba cargada"
// (la dedupe del API los frenaba, pero desde afuera parecia que algo exploto).
// Llamar a getUpdates con un offset mayor CONFIRMA esos updates del lado de
// Telegram: no los vuelve a entregar a nadie, tampoco a una ejecucion paralela
// que todavia tenga el offset viejo. Incidente real: 2026-08-14.
if (maxId >= offset) {
  try {
    await this.helpers.httpRequest({
      url: `https://api.telegram.org/bot${token}/getUpdates`,
      qs: { offset: maxId + 1, timeout: 0, limit: 1 },
      json: true,
      timeout: 20000,
    });
  } catch (e) {
    // Si el ACK falla, la static data sigue siendo la red de contencion: se
    // reprocesa a lo sumo una vez mas y la dedupe del API lo absorbe.
    console.log('No se pudo confirmar el offset en Telegram: ' + (e.message ?? e));
  }
}
if (rechazados.length) {
  console.log(
    'Descartados por la whitelist: ' + rechazados.join(', ') +
    ' | TELEGRAM_ALLOWED_IDS actual: ' + (permitidos.join(', ') || '(vacia)') +
    ' | Se acepta el ID numerico o el @usuario: copiar de aca cualquiera de los dos.',
  );
}
return out;

// getFile devuelve un file_path; el binario se baja de /file/bot<token>/<path>.
// Se hace en un Code node (y no en dos HTTP Request) para tener el buffer en
// memoria y calcular el sha256 sin pasar por disco.
const token = $env.TELEGRAM_BOT_TOKEN;
const out = [];
for (const item of $input.all()) {
  const { fileId, chatId } = item.json;
  const meta = await this.helpers.httpRequest({
    url: `https://api.telegram.org/bot${token}/getFile`,
    qs: { file_id: fileId }, json: true,
    timeout: 20000,
  });
  if (!meta.ok) throw new Error('getFile fallo: ' + JSON.stringify(meta));
  const filePath = meta.result.file_path;
  const buf = await this.helpers.httpRequest({
    url: `https://api.telegram.org/file/bot${token}/${filePath}`,
    encoding: 'arraybuffer',
    // Mas generoso que el poll: aca se baja una foto de verdad.
    timeout: 60000,
  });
  const bin = Buffer.from(buf);
  // sha256 del archivo = la idempotencia mas fuerte (la MISMA foto reenviada no
  // duplica). Va en try/catch porque el Code node corre en el task runner de
  // n8n, que arranca con la lista de modulos builtin VACIA: sin
  // NODE_FUNCTION_ALLOW_BUILTIN=crypto en el entorno, este require tira
  // "Module 'crypto' is disallowed" y se lleva puesta la ejecucion entera
  // DESPUES de haber bajado el archivo. El installer setea la variable; el
  // catch es para que un entorno desactualizado degrade en vez de romper:
  // sin hash el programa deriva uno del contenido OCR (ver ingest.ts), que
  // igual frena el duplicado, solo que gastando una pasada de OCR.
  let hash;
  try {
    hash = require('crypto').createHash('sha256').update(bin).digest('hex');
  } catch (e) {
    console.log('Sin sha256 del archivo (' + e.message + '). Falta '
      + 'NODE_FUNCTION_ALLOW_BUILTIN=crypto en el entorno de n8n. Sigo: el '
      + 'programa deriva el hash del contenido.');
  }
  const nombre = filePath.split('/').pop() || 'factura';
  const mime = nombre.toLowerCase().endsWith('.pdf') ? 'application/pdf' : 'image/jpeg';
  out.push({
    json: { chatId, hash, nombre, mime },
    binary: { data: await this.helpers.prepareBinaryData(bin, nombre, mime) },
  });
}
return out;

