parameters.jsCode:
// Mapea la salida del OCR al contrato de POST /api/v1/ingest/facturas.
// El contrato del programa SI esta verificado (apps/api/src/routes/ingest.ts).
//
// El nodo de LlamaCloud devuelve SOLO { result: "<json stringificado>" } — no
// arrastra el chatId ni el hash. Se recuperan de "Bajar archivo" por
// pairedItem: el nodo emite exactamente un item por entrada, en orden, incluso
// cuando falla (onError: continueRegularOutput).
const bajados = $('Bajar archivo').all();
const entradas = $input.all();
const out = [];

for (let i = 0; i < entradas.length; i++) {
  const item = entradas[i];
  const par = item.pairedItem;
  const idx = typeof par === 'number' ? par : (par?.item ?? i);
  const previo = bajados[idx]?.json ?? bajados[i]?.json ?? {};
  const chatId = previo.chatId;
  const hash = previo.hash;

  let crudo = null;
  let motivoFallo = item.json.error ? String(item.json.error) : null;
  if (!motivoFallo) {
    try {
      crudo = typeof item.json.result === 'string'
        ? JSON.parse(item.json.result)
        : (item.json.result ?? null);
    } catch (e) {
      motivoFallo = 'el OCR devolvio algo que no es JSON';
    }
  }

  // El schema del nodo devuelve la forma de abajo tal cual; el `?? crudo.data`
  // es red por si LlamaCloud llegara a envolver el resultado.
  const d = crudo?.data ?? crudo ?? {};
  const leer = (...rutas) => {
    for (const r of rutas) {
      let v = d;
      for (const k of r.split('.')) v = v?.[k];
      if (v !== undefined && v !== null && v !== '') return v;
    }
    return undefined;
  };
  const num = (v) => {
    if (v === undefined || v === null || v === '') return undefined;
    if (typeof v === 'number') return Number.isFinite(v) ? v : undefined;
    const n = Number(String(v).replace(/[^0-9.,-]/g, '').replace(/\.(?=\d{3}\b)/g, '').replace(',', '.'));
    return Number.isFinite(n) ? n : undefined;
  };

  const total = num(leer('montos.total', 'total', 'importe_total'));
  const proveedor = leer('proveedor.nombre', 'proveedor', 'razon_social', 'emisor.nombre');
  const numero = leer('comprobante.numero', 'numero', 'nro_comprobante');
  const fechaEmision = leer('comprobante.fechaEmision', 'fecha_emision', 'fecha');

  // QUE SE EXIGE Y QUE NO.
  //
  // Buena parte de lo que entra al local no es comprobante fiscal en regla:
  // remitos, tickets, papeles sin numerar. Exigir el numero de comprobante
  // rebotaba justamente esas, que es la mitad del laburo que se queria
  // ahorrar. Se piden SOLO las dos cosas sin las cuales la factura no
  // significa nada: DE QUIEN es y CUANTO es. Todo lo demas entra como
  // faltante, la factura se carga igual SIN VALIDAR, y la encargada completa
  // lo que haga falta cuando la revisa.
  const problemas = [];
  if (motivoFallo) problemas.push('el OCR devolvio error: ' + motivoFallo);
  if (!total || total <= 0) problemas.push('no se leyo el importe total');
  if (!proveedor) problemas.push('no se leyo de que proveedor es');

  if (problemas.length) {
    out.push({ json: { chatId, error: true, problemas } });
    continue;
  }

  // Lo que falto pero NO bloquea. Va escrito en la factura para que quien
  // revisa sepa exactamente que mirar, en vez de tener que comparar todo.
  const faltantes = [];
  if (!numero) faltantes.push('numero de comprobante');
  if (!fechaEmision) faltantes.push('fecha de emision');
  if (!leer('comprobante.tipo', 'tipo')) faltantes.push('tipo de comprobante');
  if (!leer('proveedor.cuit', 'cuit')) faltantes.push('CUIT del proveedor');

  const items = (leer('items', 'detalle', 'lineas') || []).map((it) => ({
    descripcion: String(it.descripcion ?? it.description ?? it.detalle ?? '').slice(0, 300),
    cantidad: num(it.cantidad ?? it.quantity),
    unidad: it.unidad ?? it.unit,
    precioUnitario: num(it.precioUnitario ?? it.precio_unitario ?? it.unit_price),
    alicuotaIva: num(it.alicuotaIva ?? it.iva),
    subtotal: num(it.subtotal ?? it.importe),
  })).filter((it) => it.descripcion);

  // Descuadre: no bloquea (el humano valida igual) pero baja la confianza y
  // deja la razon escrita para que quien revisa sepa donde mirar.
  // Los renglones suelen venir NETOS y el total CON IVA, asi que compararlos
  // contra el total marcaba descuadre en casi toda factura A bien discriminada.
  // Un aviso que salta siempre no lo lee nadie. Se acepta que los items cierren
  // contra el neto O contra el total; solo si no cierran con ninguno hay algo
  // raro de verdad.
  const suma = items.reduce((a, it) => a + (it.subtotal || 0), 0);
  const neto = num(leer('montos.neto', 'neto'));
  const cierraCon = (base) => base > 0 && Math.abs(base - suma) <= base * 0.05;
  const descuadra = items.length > 0 && !cierraCon(total) && !cierraCon(neto ?? 0);
  if (!items.length) faltantes.push('el detalle de productos');

  // El programa exige un numero de comprobante (es NOT NULL y forma parte de
  // la clave que evita duplicados). Cuando la factura no lo tiene, se arma uno
  // derivado de la fecha y el total: se ve claramente que es "sin numero", y
  // como sale del CONTENIDO, la misma factura fotografiada dos veces genera el
  // mismo y el duplicado se sigue frenando. Un 'S/N' fijo no serviria: dos
  // facturas distintas del mismo proveedor chocarian y la segunda se perderia
  // como "duplicada".
  const fechaFinal = fechaEmision ?? new Date().toISOString().slice(0, 10);
  const numeroFinal = numero
    ? String(numero).slice(0, 40)
    : ('S/N-' + String(fechaFinal).slice(0, 10) + '-' + Math.round(total));

  const notas = [];
  if (descuadra) notas.push('los items no suman el total');
  if (faltantes.length) notas.push('la factura vino sin: ' + faltantes.join(', '));
  if (!numero) notas.push('el numero es provisorio, ponele el real si corresponde');

  out.push({ json: {
    chatId,
    _resumen: { proveedor, total, faltantes },
    payload: {
      adjunto: { hash },
      proveedor: { nombre: String(proveedor).slice(0, 120), cuit: leer('proveedor.cuit', 'cuit') },
      comprobante: {
        tipo: leer('comprobante.tipo', 'tipo') ?? 'OTRO',
        puntoVenta: leer('comprobante.puntoVenta', 'punto_venta'),
        numero: numeroFinal,
        fechaEmision: fechaFinal,
        fechaVencimiento: leer('comprobante.fechaVencimiento', 'fecha_vencimiento'),
      },
      montos: {
        neto: num(leer('montos.neto', 'neto')),
        ivaTotal: num(leer('montos.ivaTotal', 'iva')),
        iva21: num(leer('montos.iva21')),
        iva10_5: num(leer('montos.iva10_5')),
        total,
      },
      items,
      // La confianza baja con cada cosa que falto: es lo que ordena la bandeja
      // de revision, y una factura a la que le falta medio encabezado no tiene
      // que aparecer igual de confiable que una completa.
      ocr: {
        confianza: Math.max(0.2, 0.85 - faltantes.length * 0.1 - (descuadra ? 0.25 : 0)),
        payload: crudo,
      },
      observaciones: notas.length ? ('Revisar: ' + notas.join('; ')) : undefined,
    },
  }});
}
return out;

// Un solo nodo arma TODAS las respuestas y las manda. Centralizarlo evita que
// una rama quede muda (que es como se pierde una factura sin que nadie note).
//
// A este nodo le llegan items de TRES lugares distintos, y no todos traen los
// mismos campos:
//   1. "Trae archivo?" (falso)  -> { chatId, sinArchivo }
//   2. "Se pudo leer?" (falso)  -> { chatId, error, problemas }
//   3. "Cargar en el programa"  -> { body, headers, statusCode }  <-- SIN chatId
//
// El caso 3 es la trampa: el nodo HTTP REEMPLAZA el json del item por la
// respuesta, asi que se lleva puesto el chatId y el resumen. Con el
// `if (!chatId) continue` de antes, la rama de EXITO terminaba en verde sin
// mandar nada: la factura se cargaba y nadie se enteraba. Las ramas de error
// si contestaban (traen chatId), y esa asimetria fue la pista.
const token = $env.TELEGRAM_BOT_TOKEN;
const plata = (n) => Number(n || 0).toLocaleString('es-AR', { minimumFractionDigits: 2 });

const entradas = $input.all();
for (let i = 0; i < entradas.length; i++) {
  const j = entradas[i].json;
  let chatId = j.chatId;
  let resumen = j._resumen;

  if (!chatId) {
    // Recuperar el contexto del item que le dio origen en "Armar factura".
    let ctx = null;
    try {
      ctx = $('Armar factura').itemMatching(i)?.json ?? null;
    } catch (e) {
      ctx = null;   // itemMatching no siempre esta disponible; hay plan B
    }
    if (!ctx) {
      const par = entradas[i].pairedItem;
      const idx = typeof par === 'number' ? par : (par?.item ?? i);
      const armadas = $('Armar factura').all();
      ctx = armadas[idx]?.json ?? armadas[i]?.json ?? null;
    }
    chatId = ctx?.chatId;
    resumen = resumen ?? ctx?._resumen;
  }

  if (!chatId) {
    // Si esto aparece, alguien se quedo sin respuesta: hay que saberlo.
    console.log('Sin chatId para el item ' + i + ': no le puedo contestar a nadie. '
      + 'Item: ' + JSON.stringify(j).slice(0, 300));
    continue;
  }

  let texto;
  if (j.sinArchivo) {
    texto = 'Mandame una *foto* o un *PDF* de la factura.';
  } else if (j.error && j.problemas) {
    texto = '⚠️ No pude leer la factura (' + (j.problemas || []).join('; ') + ').\n'
          + 'Probá con una foto más nítida y derecha, o cargala a mano en el sistema.';
  } else {
    const code = j.statusCode;
    const body = j.body ?? {};
    const r = resumen ?? {};
    const faltantes = (r.faltantes || []).length
      ? '\n📝 Sin leer: ' + r.faltantes.join(', ') + '. Completalo al revisarla.'
      : '';
    if (code === 201) {
      // El id va en el mensaje a proposito: si despues no aparece en la
      // pantalla, tener el id permite saber si el problema es que no se creo
      // o que se esta mirando otra base. Sin el, hay que adivinar.
      texto = `✅ Factura de *${r.proveedor}* por $${plata(r.total)} cargada.\n`
            + 'Queda *sin validar*: revisala y aceptala en Admin → Facturas.' + faltantes
            + (body.id ? `\n🔖 id: \`${body.id}\`` : '');
    } else if (code === 200 && body.duplicate) {
      texto = 'ℹ️ Esa factura ya estaba cargada'
            + (body.id ? ` (id: \`${body.id}\`)` : '') + '.';
    } else if (code === 503) {
      texto = '⚠️ La ingesta está deshabilitada en el servidor (falta INGEST_API_TOKEN).';
    } else if (code === 401) {
      texto = '⚠️ El token de ingesta es inválido. Avisale al que administra el sistema.';
    } else if (!code) {
      // Ni siquiera hubo respuesta: el programa no estaba escuchando. Pasa
      // siempre en una PC de pruebas, donde INGEST_URL apunta a un localhost
      // sin server. Decirlo con todas las letras ahorra media hora de buscar.
      texto = '⚠️ No pude contactar al programa para cargarla.\n'
            + 'Revisá que INGEST_URL apunte a un servidor que este andando '
            + '(en una PC de pruebas normalmente no hay ninguno).';
    } else {
      texto = `⚠️ El sistema rechazó la factura (${code}). Cargala a mano por ahora.`;
    }
  }

  await this.helpers.httpRequest({
    method: 'POST',
    url: `https://api.telegram.org/bot${token}/sendMessage`,
    body: { chat_id: chatId, text: texto, parse_mode: 'Markdown' },
    json: true,
    timeout: 20000,
  });
}
return entradas;
